{
 "method": "POST",
 "path": "/api/v1/session-leases",
 "tags": [
 ],
 "summary": "Acquire, renew, or release an exclusive managed connection lease",
 "description": "Requires an API key with `lease:exclusive` and an explicit non-empty\n`allowedConnections` policy. The opaque owner is bound to the authenticated API key;\nthe lease owns an eligible connection, not a provider or model. Managed inference\nrequests present the owner and exact generation headers. Temporary foreign occupancy\nreturns 429 `WAITING_FOR_CAPACITY` with `Retry-After`.\n",
 "security": true,
 "parameters": [
  {
   "name": "X-OmniRoute-Lease-Owner",
   "in": "header",
   "required": true,
   "schema": {
    "type": "string",
    "pattern": "^vlo_[A-Za-z0-9_-]{43}$"
   }
  }
 ],
 "requestBody": true,
 "exampleBody": {
  "action": "string",
 },
 "responses": [
  "200",
  "400",
  "401",
  "403",
  "409",
  "415",
 ],
 "loopbackOnly": false,
 "alwaysProtected": false,
}

